ruleSearch.bookList:
#nr
<js>
result.toArray().slice(0,5).map(o=>{
    var detail = o.select('.odd a').attr('href');
    var J = org.jsoup.Jsoup.parse(java.ajax(detail));
    return {
       name:  o.select('.odd a').text(),
       author:o.select('.odd:eq(2)').text(),
       tags: J.select('meta[property="og:novel:category"]').attr('content'),
       num:o.select('.even:eq(3)').text()+'字',
       latest: String(o.select('.even a').text()).replace(/(正文)?(\s+|_)/,'').replace(/[\(（【].*[求更谢乐发推].*[】）\)]/,'')+String(o.select('.odd:eq(4)').text()).replace(/(\d+-\d+-\d+).*/,'（$1）'),
       intro: String(J.select('#intro p:eq(0)').text()).replace('简介：','').trim(),
       cover: J.select('img').attr('src'),
       catalogUrl: detail
    }
});
</js>

